<?php
namespace Alprof\Services;
use RuntimeException;
final class EncryptionService { private string $key; public function __construct(){ $raw=base64_decode((string)envv('APP_DATA_KEY',''),true); if($raw===false||strlen($raw)!==SODIUM_CRYPTO_SECRETBOX_KEYBYTES) throw new RuntimeException('APP_DATA_KEY is invalid.'); $this->key=$raw;} public function encrypt(string $plain):string{$nonce=random_bytes(SODIUM_CRYPTO_SECRETBOX_NONCEBYTES);return base64_encode($nonce.sodium_crypto_secretbox($plain,$nonce,$this->key));} public function decrypt(string $encoded):string{$data=base64_decode($encoded,true);if($data===false||strlen($data)<=SODIUM_CRYPTO_SECRETBOX_NONCEBYTES)throw new RuntimeException('Invalid encrypted value.');$nonce=substr($data,0,SODIUM_CRYPTO_SECRETBOX_NONCEBYTES);$plain=sodium_crypto_secretbox_open(substr($data,SODIUM_CRYPTO_SECRETBOX_NONCEBYTES),$nonce,$this->key);if($plain===false)throw new RuntimeException('Decryption failed.');return $plain;} public function blindIndex(string $value):string{return hash_hmac('sha256',preg_replace('/\D+/','',$value),$this->key);} }
